import re

CARD = re.compile(r"\b(?:\d[ -]?){13,18}\d\b")    # 14 to 19 digits
KEYWORDS = ("cvv", "cvc", "security code", "expiry", "card")

def luhn_ok(digits: str) -> bool:
    total = 0
    for i, ch in enumerate(reversed(digits)):
        d = int(ch)
        if i % 2 == 1:          # every second digit from the right
            d *= 2
            if d > 9:
                d -= 9
        total += d
    return total % 10 == 0

def scan(text: str):
    for m in CARD.finditer(text):
        digits = re.sub(r"\D", "", m.group())
        if not luhn_ok(digits):
            continue                         # random 16 digits: dropped
        window = text[max(0, m.start() - 300): m.end() + 300].lower()
        near = any(k in window for k in KEYWORDS)
        yield digits[-4:], "high" if near else "low"

