import re

# Simplified rows shaped like a query-history export: (session, user, query_text)
history = [
    (901, "etl_svc", "COPY INTO sales FROM @landing/2026-11-21/"),
    (902, "j.doe",   "SHOW TABLES"),
    (902, "j.doe",   "CREATE TEMPORARY STAGE crm.public.s1"),
    (902, "j.doe",   "COPY INTO @crm.public.s1/out FROM (SELECT * FROM crm.public.customers) FILE_FORMAT=(COMPRESSION=GZIP)"),
    (902, "j.doe",   "GET @crm.public.s1/out file:///tmp/"),
    (903, "analyst", "SELECT region, COUNT(*) FROM crm.public.customers GROUP BY 1"),
]
STEPS = [r"^SHOW TABLES", r"^CREATE TEMP(ORARY)? STAGE", r"^COPY INTO @", r"^GET @"]

sessions = {}
for sid, user, q in history:
    for i, pat in enumerate(STEPS):
        if re.search(pat, q, re.I):
            sessions.setdefault((sid, user), set()).add(i)

for (sid, user), seen in sessions.items():
    verdict = "ALERT: stage-and-download pattern" if len(seen) == len(STEPS) else "ok"
    print(sid, user, sorted(seen), verdict)

import hashlib, re, secrets

SALT = secrets.token_bytes(16)          # kept with the hashed table, not public

def h(value: str) -> str:
    return hashlib.sha256(SALT + value.encode()).hexdigest()

# 1. The data owner hashes the real customer table and uploads only hashes.
customers = [("123-45-6789", "Ruiz"), ("987-65-4321", "Park")]
table = {h(ssn): h(last.lower()) for ssn, last in customers}

SSN = re.compile(r"\b\d{3}-\d{2}-\d{4}\b")      # the primary element's pattern

def edm_scan(text: str):
    words = {h(w.lower()) for w in re.findall(r"[A-Za-z]+", text)}
    for m in SSN.finditer(text):
        row = table.get(h(m.group()))
        if row is None:
            yield m.group()[-4:], "pattern only, not our customer"
        elif row in words:
            yield m.group()[-4:], "EXACT: our customer, name nearby"
        else:
            yield m.group()[-4:], "EXACT: our customer"

print(list(edm_scan("Refund for A. Ruiz, SSN 123-45-6789")))
print(list(edm_scan("Form example: 900-12-3456")))

