from datetime import date

# (day, user, event, detail) from HR, file audit and endpoint DLP logs
events = [
    (date(2026, 9, 1),  "u17", "resignation", "last day 2026-09-19"),
    (date(2026, 9, 3),  "u17", "download",    "412 files from /eng/battery"),
    (date(2026, 9, 4),  "u17", "usb_copy",    "380 files, 2.1 GB"),
    (date(2026, 9, 3),  "u42", "download",    "35 files from /eng/battery"),
    (date(2026, 9, 10), "u42", "usb_copy",    "2 files, 4 MB"),
]
BASELINE_FILES_PER_DAY = {"u17": 20, "u42": 30}   # each user's own normal

def risk(user: str) -> int:
    score, resigned = 0, None
    for day, u, ev, detail in sorted(e for e in events if e[1] == user):
        if ev == "resignation":
            resigned = day
        elif ev == "download":
            n = int(detail.split()[0])
            if n > 5 * BASELINE_FILES_PER_DAY[u]:
                score += 30                    # unusual volume for this person
        elif ev == "usb_copy":
            score += 20
        if resigned and ev != "resignation":
            score += 25                        # activity inside the departure window
    return score

for u in ("u17", "u42"):
    print(u, risk(u), "review" if risk(u) >= 70 else "no alert")
